class DataProcessor {
public:
  // A strong promise: this function will never propagate an exception.
  // Clients can rely on this for performance and exception safety.
  void process() noexcept;
};

// If a future version of process() needs to throw, the author faces a dilemma:
// 1. Change to 'void process();' -> Breaks client code that relied on noexcept.
// 2. Keep 'noexcept' but let an exception escape -> Program terminates via std::terminate.
// 3. Keep 'noexcept' but swallow the exception -> Hides critical errors from the caller.
